#!/usr/bin/env node
/**
 * GDX_SKILL_RECORD_NEW_STUDY - stage 2: execute the scripts generated by
 * generate_new_study_scripts.py against a live Firebird database, over the
 * wire protocol (node-firebird), no native Firebird client library required.
 *
 * Dual-mode statement runner: a file whose content starts with
 * `EXECUTE BLOCK` (case-insensitive) is sent to Firebird as ONE statement
 * (naive split-on-';' would butcher its internal PSQL) -- everything else
 * (currently unused here, kept for a future flat-INSERT-only file) is split
 * into individual statements the same safe way GDX_SKILL_LOAD_RLT_MODEL_DB's
 * execute_load.js does.
 *
 * Connection is read ENTIRELY from environment variables -- nothing is
 * hardcoded here on purpose (see CLAUDE.md: don't hardcode Firebird
 * credentials as defaults). Copy .env.example to .env (gitignored) and fill
 * it in, or export the vars in your shell before running. This is the SAME
 * database as GDX_SKILL_LOAD_RLT_MODEL_DB / GDX_SKILL_NEW_STUDY.
 *
 * Required env vars:
 *   GDX_HUMAN_FB_HOST, GDX_HUMAN_FB_PORT, GDX_HUMAN_FB_DATABASE,
 *   GDX_HUMAN_FB_USER, GDX_HUMAN_FB_PASSWORD
 *
 * Usage:
 *   node execute_new_study.js --dir <folder> [--dry-run]
 *
 *   --dir       folder containing 01_new_study.sql and 02_new_instrument_*.sql
 *               (normally GDX_HUMAN/0.new.instrument/new_study_intake/<slug>/)
 *   --dry-run   parse and count statements per file, connect and run the
 *               preflight schema check, but execute nothing
 *
 * There is deliberately no --force / "already loaded" guard here like
 * execute_load.js's: 01_new_study.sql is idempotent by TITLE (see its own
 * generated comment) and every 02_new_instrument_*.sql fails loudly on
 * Firebird's own (NAME, VERSION) UNIQUE constraint if the instrument already
 * exists -- that IS the duplicate guard, enforced by the schema itself.
 */

const fs = require('fs');
const path = require('path');
const Firebird = require('node-firebird');

const REQUIRED_TABLES = [
  'GDX_PSY_STUDY', 'GDX_PSY_PHENOMENON', 'GDX_PSY_CONSTRUCT', 'GDX_PSY_VARIABLE',
  'GDX_PSY_INDICATOR', 'GDX_PSY_INSTRUMENT', 'GDX_PSY_INSTRUMENT_CONSTRUCT',
  'GDX_PSY_INSTRUMENT_ITEM', 'GDX_PSY_ITEM_ALTERNATIVE', 'GDX_PSY_INDICATOR_ITEM',
];

function parseArgs(argv) {
  const args = { dir: null, dryRun: false };
  for (let i = 2; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--dir') args.dir = argv[++i];
    else if (a === '--dry-run') args.dryRun = true;
    else throw new Error(`Unknown argument: ${a}`);
  }
  if (!args.dir) throw new Error('--dir <folder> is required (the folder with 01_new_study.sql etc.)');
  return args;
}

function requireEnv(name) {
  const v = process.env[name];
  if (!v) {
    throw new Error(
      `Missing required environment variable ${name}. Copy .env.example to .env in this ` +
      `skill's folder, fill it in, and export the vars before running this script. ` +
      `Never hardcode credentials in this file or in git.`
    );
  }
  return v;
}

function listGeneratedFiles(dir) {
  const all = fs.readdirSync(dir).filter((f) => f.endsWith('.sql'));
  const study = all.filter((f) => f === '01_new_study.sql');
  const instruments = all.filter((f) => /^02_new_instrument_\d+_/.test(f)).sort();
  return [...study, ...instruments].map((f) => path.join(dir, f));
}

/** Same string-aware splitter as execute_load.js, for any non-EXECUTE-BLOCK file. */
function stripLineComments(text) {
  let out = '';
  let inString = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (ch === "'") {
      inString = !inString;
      out += ch;
      continue;
    }
    if (!inString && ch === '-' && text[i + 1] === '-') {
      let j = text.indexOf('\n', i);
      if (j === -1) j = text.length;
      i = j - 1;
      continue;
    }
    out += ch;
  }
  return out;
}

function splitFlatStatements(text) {
  const statements = [];
  let current = '';
  let inString = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (ch === "'") inString = !inString;
    if (ch === ';' && !inString) {
      const stmt = current.trim();
      if (stmt) statements.push(stmt);
      current = '';
    } else {
      current += ch;
    }
  }
  const rest = current.trim();
  if (rest) throw new Error(`Trailing content without terminating ';': ${rest.slice(0, 120)}`);
  return statements;
}

function stripHeaderComment(sqlText) {
  return sqlText.replace(/^\s*\/\*[\s\S]*?\*\/\s*/, '');
}

/** Returns { mode: 'block', statement } or { mode: 'flat', statements: [...] }. */
function parseFile(sqlText) {
  const body = stripHeaderComment(sqlText).trim();
  if (/^EXECUTE\s+BLOCK/i.test(body)) {
    return { mode: 'block', statement: body };
  }
  return { mode: 'flat', statements: splitFlatStatements(stripLineComments(body)) };
}

function connect(options) {
  return new Promise((resolve, reject) => {
    Firebird.attach(options, (err, db) => (err ? reject(err) : resolve(db)));
  });
}

function query(db, sql) {
  return new Promise((resolve, reject) => {
    db.query(sql, (err, result) => (err ? reject(err) : resolve(result)));
  });
}

function startTransaction(db) {
  return new Promise((resolve, reject) => {
    db.transaction(Firebird.ISOLATION_READ_COMMITTED, (err, tr) => (err ? reject(err) : resolve(tr)));
  });
}

function txQuery(tr, sql) {
  return new Promise((resolve, reject) => {
    tr.query(sql, (err, result) => (err ? reject(err) : resolve(result)));
  });
}

function commit(tr) {
  return new Promise((resolve, reject) => {
    tr.commit((err) => (err ? reject(err) : resolve()));
  });
}

function rollback(tr) {
  return new Promise((resolve) => {
    tr.rollback(() => resolve());
  });
}

async function tableExists(db, name) {
  const rows = await query(db, `SELECT 1 FROM RDB$RELATIONS WHERE RDB$RELATION_NAME = '${name}'`);
  return rows.length > 0;
}

async function preflight(db) {
  const missing = [];
  for (const t of REQUIRED_TABLES) {
    if (!(await tableExists(db, t))) missing.push(t);
  }
  if (missing.length) {
    throw new Error(
      `Target database is missing required table(s): ${missing.join(', ')}.\n` +
      `Apply GDX_HUMAN/2.relational.model.psychometrics/psychometrics_model_firebird25.sql ` +
      `(the DDL) on this database first, then re-run this script.`
    );
  }
}

async function runFile(db, filePath, dryRun) {
  const parsed = parseFile(fs.readFileSync(filePath, 'utf8'));
  const name = path.basename(filePath);

  if (parsed.mode === 'block') {
    console.log(`${name}: 1 EXECUTE BLOCK statement`);
    if (dryRun) return 1;
    const tr = await startTransaction(db);
    try {
      await txQuery(tr, parsed.statement);
      await commit(tr);
    } catch (err) {
      await rollback(tr);
      throw new Error(`Failed in ${name}: ${err.message}`);
    }
    return 1;
  }

  console.log(`${name}: ${parsed.statements.length} statement(s)`);
  if (dryRun) return parsed.statements.length;
  const tr = await startTransaction(db);
  try {
    for (const stmt of parsed.statements) {
      await txQuery(tr, stmt);
    }
    await commit(tr);
  } catch (err) {
    await rollback(tr);
    throw new Error(`Failed in ${name}: ${err.message}`);
  }
  return parsed.statements.length;
}

async function main() {
  const args = parseArgs(process.argv);

  const options = {
    host: requireEnv('GDX_HUMAN_FB_HOST'),
    port: parseInt(requireEnv('GDX_HUMAN_FB_PORT'), 10),
    database: requireEnv('GDX_HUMAN_FB_DATABASE'),
    user: requireEnv('GDX_HUMAN_FB_USER'),
    password: requireEnv('GDX_HUMAN_FB_PASSWORD'),
    lowercase_keys: false,
    role: null,
    pageSize: 4096,
  };

  const files = listGeneratedFiles(args.dir);
  if (files.length === 0) {
    throw new Error(`No 01_new_study.sql / 02_new_instrument_*.sql found in ${args.dir}`);
  }

  console.log(`Connecting to ${options.host}:${options.port}${options.database} as ${options.user} ...`);
  const db = await connect(options);
  try {
    await preflight(db);

    let total = 0;
    for (const file of files) {
      total += await runFile(db, file, args.dryRun);
    }
    console.log(args.dryRun
      ? `Dry run complete. ${total} statement(s) would be executed across ${files.length} file(s).`
      : `Done. ${total} statement(s) executed and committed across ${files.length} file(s).`);
  } finally {
    db.detach();
  }
}

if (require.main === module) {
  main().catch((err) => {
    console.error('ERROR:', err.message);
    process.exit(1);
  });
}

module.exports = { parseFile };
